export function getEquippedSlot(equipment, itemId) {
  if (!equipment || !Number.isInteger(itemId) || itemId <= 0) return null;
  for (const slot of GEAR_SLOTS) {
    if (equipment[slot] === itemId) return slot;
  }
  return null;
}

